+// SPDX-License-Identifier: Apache-2.0
+
+use std::process::Command;
+
+use serde_json::Value;
+
+#[test]
+fn reviewgraphen_generated_regression() {
+    let directory = std::env::temp_dir().join(format!(
+        "fslc-reviewgraphen-calibration-15-{}-{:?}",
+        std::process::id(),
+        std::thread::current().id()
+    ));
+    std::fs::create_dir_all(&directory).expect("create scratch directory");
+    let path = directory.join("malformed-ai-project.fsl");
+    std::fs::write(
+        &path,
+        "statistical_property Quality {\n  confidence not_a_number\n}\n",
+    )
+    .expect("write malformed AI project");
+
+    let output = Command::new(env!("CARGO_BIN_EXE_fslc"))
+        .args(["check", path.to_str().expect("UTF-8 scratch path")])
+        .output()
+        .expect("run fslc check");
+    std::fs::remove_dir_all(&directory).expect("remove scratch directory");
+
+    assert_eq!(output.status.code(), Some(2));
+    assert!(output.stderr.is_empty());
+    let value: Value = serde_json::from_slice(&output.stdout).expect("JSON error envelope");
+    assert_eq!(value["result"], "error");
+    assert_eq!(value["kind"], "semantics");
+    assert!(
+        value["message"]
+            .as_str()
+            .is_some_and(|message| message.contains("non-numeric confidence"))
+    );
+}
